const delay = (ms, value) =>
  new Promise((resolve) => setTimeout(() => resolve(value), ms));

const fail = (ms, message) =>
  new Promise((resolve, reject) => setTimeout(() => reject(new Error(message)), ms));

Promise.race([fail(50, "late error"), delay(10, "early value")])
  .then((value) => console.log("first: " + value))
  .catch((error) => console.log("first: " + error.message));

Promise.race([delay(50, "late value"), fail(30, "early error")])
  .then((value) => console.log("second: " + value))
  .catch((error) => console.log("second: " + error.message));
